mapper.select:
SELECT m.id AS merchant_id,
m.name,
m.address,
m.thumbnail_url,
m.price,
m.rating,
COALESCE(COUNT(r.review_id), 0) AS review_count,
o.noise_level,
0 AS bookmarked
FROM merchants m
INNER JOIN offices o
ON o.merchant_id = m.id
LEFT JOIN reviews r
ON r.merchant_id = m.id
AND r.status = 'ACTIVE'
WHERE m.category = 'OFFICE'


    AND m.region_id = #{regionId}




    AND EXISTS (
    SELECT 1
    FROM reservation_products rp
    INNER JOIN product_daily_inventories pdi
    ON pdi.product_id = rp.id
    WHERE rp.merchant_id = m.id
    AND pdi.inventory_date BETWEEN #{startDate} AND #{endDate}
    AND pdi.is_available = 1
    AND pdi.remaining_capacity > 0
    )



    AND (
    m.rating  <  #{cursorRating}
    OR (
    m.rating = #{cursorRating}
    AND m.id  <  #{cursorMerchantId}
    )
    )


    AND (
    m.rating  >  #{cursorRating}
    OR (
    m.rating = #{cursorRating}
    AND m.id  >  #{cursorMerchantId}
    )
    )


    AND (
    m.price  >  #{cursorPrice}
    OR (
    m.price = #{cursorPrice}
    AND m.id  >  #{cursorMerchantId}
    )
    )


    AND (
    m.price  <  #{cursorPrice}
    OR (
    m.price = #{cursorPrice}
    AND m.id  <  #{cursorMerchantId}
    )
    )


GROUP BY m.id,
m.name,
m.address,
m.thumbnail_url,
m.price,
m.rating,
o.noise_level



        ORDER BY m.rating ASC,
        m.id ASC


        ORDER BY m.price ASC,
        m.id ASC


        ORDER BY m.price DESC,
        m.id DESC


        ORDER BY m.rating DESC,
        m.id DESC



LIMIT #{size}
